INSERT INTO `job_logglue` (`id`, `job_id`, `glue_type`, `glue_source`, `glue_remark`, `create_time`, `update_time`) VALUES (31, 794, 'BEAN', 'package com.xxl.job.service.handler;\n\n            import com.xxl.job.core.context.XxlJobHelper;\n            import com.xxl.job.core.handler.IJobHandler;\n            \n            public class DemoGlueJobHandler extends IJobHandler {\n            \n            	@Override\n            	public void execute() throws Exception {\n            		  XxlJobHelper.log(\">>>>>>>> GLUE demoJobHandler5 start\");\n\n                    for (int i = 0; i < 10; i++) {\n                        XxlJobHelper.log(\" GLUEd emoJobHandler5 beat at:\" + i);\n                        System.out.println(\" GLUE demoJobHandler5 beat at:\" + i);\n                        TimeUnit.MILLISECONDS.sleep(500);\n                    }\n                    XxlJobHelper.log(\">>>>>>>> GLUE demoJobHandler5 end\");\n            	}\n            }\n            ', 'demo5-1', '2025-03-29 12:20:53', '2025-03-29 12:20:53');
